class TestYamlToVeoJson:
    """Test YAML to Veo JSON compilation (Task 2.2 Definition of Done)."""
    
    def test_yaml_to_veo_json(self):
        """Compiler outputs valid Veo API JSON from sample YAML."""
        yaml_content = """
shot_id: "ACT1_SC01_SHOT01"
prompt:
  text: Wide establishing shot of city at sunset
  negative: blurry, distorted faces
duration_s: 8
aspect_ratio: "16:9"
"""
        
        veo_json = compile_yaml_to_veo_json(yaml_content)
        
        # Verify required Veo API fields
        assert "prompt" in veo_json
        assert "config" in veo_json
        assert veo_json["config"]["duration_seconds"] == 8
        assert veo_json["config"]["aspect_ratio"] == "16:9"
        assert "negative_prompt" in veo_json["config"]
        assert "model" in veo_json
    
    def test_compiles_with_references(self):
        """Compiler handles reference images correctly."""
        spec = {
            "shot_id": "REF_TEST",
            "prompt": {"text": "Test with references"},
            "duration_s": 4,
            "aspect_ratio": "9:16",
            "references": {
                "subject_images": [
                    {"path": "./img1.png", "weight": 0.7},
                    {"path": "./img2.png", "weight": 0.3}
                ],
                "first_frame": "./first.png"
            }
        }
        
        veo_json = compile_yaml_to_veo_json(spec)
        
        assert "references" in veo_json
        assert len(veo_json["references"]["subject_images"]) == 2
        assert veo_json["references"]["first_frame"] == "./first.png"
    
    def test_compiles_with_controls(self):
        """Compiler handles controls (seed, safety) correctly."""
        spec = {
            "shot_id": "CTRL_TEST",
            "prompt": {"text": "Test with controls"},
            "duration_s": 8,
            "aspect_ratio": "16:9",
            "controls": {
                "seed": 12345,
                "safety": "strict"
            }
        }
        
        veo_json = compile_yaml_to_veo_json(spec)
        
        assert veo_json["config"]["seed"] == 12345
        assert veo_json["config"]["safety_filter"] == "strict"
    
    def test_metadata_preserved(self):
        """Metadata is preserved in _metadata field."""
        spec = {
            "shot_id": "META_TEST",
            "prompt": {"text": "Test"},
            "duration_s": 4,
            "aspect_ratio": "1:1",
            "metadata": {
                "scene": "SC05",
                "act": "ACT2",
                "sequence_order": 7,
                "notes": "Important shot"
            }
        }
        
        veo_json = compile_yaml_to_veo_json(spec)
        
        assert "_metadata" in veo_json
        assert veo_json["_metadata"]["shot_id"] == "META_TEST"
        assert veo_json["_metadata"]["scene"] == "SC05"


class TestValidationRejectsInvalid:
    """Test validation layer rejects invalid inputs (Task 2.3 Definition of Done)."""
    
    def test_validation_rejects_invalid_duration(self):
        """Compiler rejects shots with invalid duration."""
        invalid_spec = {
            "shot_id": "INVALID_DUR",
            "prompt": {"text": "Test"},
            "duration_s": 5,  # Not in [4, 8, 16]
            "aspect_ratio": "16:9"
        }
        
        errors = validate_shot_spec(invalid_spec)
        assert len(errors) > 0
        assert any("duration_s" in e for e in errors)
        
        with pytest.raises(ValidationError):
            compile_yaml_to_veo_json(invalid_spec)
    
    def test_validation_rejects_invalid_aspect_ratio(self):
        """Compiler rejects shots with invalid aspect ratio."""
        invalid_spec = {
            "shot_id": "INVALID_AR",
            "prompt": {"text": "Test"},
            "duration_s": 8,
            "aspect_ratio": "4:3"  # Not in [16:9, 9:16, 1:1]
        }
        
        errors = validate_shot_spec(invalid_spec)
        assert len(errors) > 0
        assert any("aspect_ratio" in e for e in errors)
    
    def test_validation_rejects_too_many_references(self):
        """Compiler rejects shots exceeding max reference count."""
        invalid_spec = {
            "shot_id": "TOO_MANY_REFS",
            "prompt": {"text": "Test"},
            "duration_s": 8,
            "aspect_ratio": "16:9",
            "references": {
                "subject_images": [
                    {"path": f"./img{i}.png", "weight": 0.5}
                    for i in range(10)  # Exceeds max of 6
                ]
            }
        }
        
        errors = validate_shot_spec(invalid_spec)
        assert len(errors) > 0
        assert any("subject_images" in e and "exceeds" in e for e in errors)
    
    def test_validation_rejects_invalid_weight(self):
        """Compiler rejects reference images with invalid weight."""
        invalid_spec = {
            "shot_id": "INVALID_WEIGHT",
            "prompt": {"text": "Test"},
            "duration_s": 8,
            "aspect_ratio": "16:9",
            "references": {
                "subject_images": [
                    {"path": "./img.png", "weight": 1.5}  # Exceeds max of 1.0
                ]
            }
        }
        
        errors = validate_shot_spec(invalid_spec)
        assert len(errors) > 0
        assert any("weight" in e for e in errors)
    
    def test_validation_rejects_missing_required_fields(self):
        """Compiler rejects shots missing required fields."""
        # Missing shot_id
        errors = validate_shot_spec({"prompt": {"text": "T"}, "duration_s": 8, "aspect_ratio": "16:9"})
        assert any("shot_id" in e for e in errors)
        
        # Missing prompt
        errors = validate_shot_spec({"shot_id": "X", "duration_s": 8, "aspect_ratio": "16:9"})
        assert any("prompt" in e for e in errors)
        
        # Missing duration_s
        errors = validate_shot_spec({"shot_id": "X", "prompt": {"text": "T"}, "aspect_ratio": "16:9"})
        assert any("duration_s" in e for e in errors)
        
        # Missing aspect_ratio
        errors = validate_shot_spec({"shot_id": "X", "prompt": {"text": "T"}, "duration_s": 8})
        assert any("aspect_ratio" in e for e in errors)
    
    def test_validation_rejects_prompt_too_long(self):
        """Compiler rejects prompts exceeding max length."""
        invalid_spec = {
            "shot_id": "LONG_PROMPT",
            "prompt": {"text": "x" * 5000},  # Exceeds 4000 char limit
            "duration_s": 8,
            "aspect_ratio": "16:9"
        }
        
        errors = validate_shot_spec(invalid_spec)
        assert len(errors) > 0
        assert any("max length" in e for e in errors)


class TestParseAndCompile:
    """Integration tests for full parse-and-compile workflow."""
    
    def test_full_workflow_yaml_string(self):
        """Full workflow from YAML string to Veo JSON."""
        yaml_str = """
shot_id: WORKFLOW_TEST
prompt:
  text: A beautiful landscape at dawn
duration_s: 16
aspect_ratio: "1:1"
renderer:
  model: veo-3.1-generate-preview
"""
        shot = parse_shot_spec(yaml_str)
        assert shot.shot_id == "WORKFLOW_TEST"
        assert shot.duration_s == 16
        
        veo_json = compile_to_veo_json(shot)
        assert veo_json["config"]["duration_seconds"] == 16
        assert veo_json["config"]["aspect_ratio"] == "1:1"


